package com.jinloes.practice;
import java.util.ArrayList; import java.util.List; import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: name@HHmm access entries separated by spaces, for example: alice@0830 alice@0850 alice@0920 bob@1200"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ", args).trim()); return; } assertThat(Solution.highAccessEmployees(List.of(a("alice","0830"),a("alice","0850"),a("alice","0920"),a("bob","1200")))).containsExactly("alice"); assertThat(Solution.highAccessEmployees(List.of(a("amy","1000"),a("amy","1030"),a("amy","1100")))).isEmpty(); assertThat(Solution.highAccessEmployees(List.of(a("zoe","0000"),a("zoe","0000"),a("zoe","0001")))).containsExactly("zoe"); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ System.out.println(Solution.highAccessEmployees(parse(input))); }catch(RuntimeException e){ System.out.println(USAGE); } } static List<Solution.Access> parse(String input){ if(input.isBlank()) return List.of(); List<Solution.Access> out=new ArrayList<>(); for(String token:input.split("\\s+")){ String[] parts=token.split("@",-1); if(parts.length!=2||parts[0].isBlank()||!parts[1].matches("\\d{4}")) throw new IllegalArgumentException(); out.add(a(parts[0],parts[1])); } return out; } static Solution.Access a(String n,String t){ return new Solution.Access(n,t); } }
